// The signature covers `${timestamp}.${rawBody}` — the bytes as sent.
// Re-serialising the parsed JSON would change key order or spacing and
// break the comparison, which is why the Webhook node is set to Raw Body.
const item = $input.first();

const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const headers = item.json.headers || {};
const signature = headers['x-webhook-signature'] || '';

const parts = Object.fromEntries(
  signature.split(',').map((segment) => {
    const i = segment.indexOf('=');
    return [segment.slice(0, i).trim(), segment.slice(i + 1).trim()];
  })
);

const timestamp = Number(parts.t);
const fresh = Number.isFinite(timestamp) && Math.abs(Date.now() / 1000 - timestamp) <= 300;

return [
  {
    json: {
      signedPayload: `${parts.t}.${rawBody}`,
      presentedSignature: parts.v1 || '',
      fresh,
      eventId: headers['x-webhook-id'] || '',
      event: JSON.parse(rawBody),
    },
  },
];

// Shape the ticket for a chat message. Swap the next node for a real
// Slack / Discord / Teams node and map `text` onto its message field.
const { data } = $json.event;

const emoji = { urgent: '🔴', high: '🟠', medium: '🟡', low: '⚪' }[data.priority] || '⚪';

return [
  {
    json: {
      eventId: $json.eventId,
      ticketNumber: data.ticketNumber,
      priority: data.priority,
      text: [
        `${emoji} *${data.ticketNumber}* — ${data.subject}`,
        `Priority: ${data.priority} · respond within ${data.slaHours}h`,
        data.orderNumber ? `Order: ${data.orderNumber}` : null,
        data.dashboardUrl,
      ]
        .filter(Boolean)
        .join('\n'),
    },
  },
];
